using System;using System.Linq;using ForteMove.Models.Operations;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Driver{public partial class CannotProceed:DriverPage{private long Id{get{long x;return long.TryParse(Request.QueryString["id"],out x)?x:0;}}protected void Page_Load(object s,EventArgs e){if(!IsPostBack)LoadContext();}private void LoadContext(){var d=ServiceFactory.CreateDriverOperationsService().GetTripDetails(CurrentPrincipalContext.UserAccountId,Id);if(d==null){Response.Redirect(ResolveUrl("~/Driver/Today.aspx"),true);return;}litContext.Text=Server.HtmlEncode(d.TripCode+" · "+d.RouteName);hidTripRv.Value=Convert.ToBase64String(d.TripRowVersion);hidAssignmentRv.Value=Convert.ToBase64String(d.AssignmentRowVersion);}protected void btnSubmit_Click(object s,EventArgs e){var r=ServiceFactory.CreateDriverOperationsService().ReportCannotProceed(new ReportCannotProceedRequest{TripId=Id,Reason=txtReason.Text,Note=txtNote.Text,TripRowVersion=Parse(hidTripRv.Value),AssignmentRowVersion=Parse(hidAssignmentRv.Value)},CurrentPrincipalContext.UserAccountId);if(r.Succeeded){Response.Redirect(ResolveUrl("~/Driver/TripDetails.aspx?id="+Id),true);return;}litError.Text=Server.HtmlEncode(string.Join(" ",r.Errors.Select(x=>x.Message)));pnlError.Visible=true;LoadContext();}private static byte[] Parse(string x){try{return Convert.FromBase64String(x);}catch{return null;}}}}
